import AppKit

extension ClipPane {
    // MARK: - Timing

    /// Where the clip sits on the ruler, and which way it runs.
    ///
    /// In and Out are the clip's own edges, typed as timecode and committed as
    /// `trim_start` / `trim_end` — the same two ops the edge drags and the two
    /// Trim to Playhead commands use, so a typed edge obeys the same rules.
    ///
    /// **Those rules CLAMP; they do not refuse** (`core/src/edit_clip.rs`, and
    /// the op table in `edit.rs` says so in one line each): `trim_start` pulls
    /// the new start back to the source head and no later than one frame
    /// before the end, `trim_end` pushes the new end to at least one frame of
    /// clip and no further than the source has left. **The core declines** —
    /// both arms beep from `applyEdit` and neither makes an undo step — when
    /// the clamped edge is where the edge already was or the two clamps cross
    /// (an IDENTITY: a clamp landing where the clip already is names no rule),
    /// and when the move breaks the overlap rule (a REFUSAL, in that rule's
    /// own sentence). So a typed value out of range does not beep: it lands
    /// clamped, and the field re-reads what the core committed. Nothing here
    /// clamps on the user's behalf, which keeps that one rule in one place.
    ///
    /// Duration is read-only because it has no op of its own: it is
    /// `end − start`, and §6 gives you the two edges instead.
    ///
    /// In, Out and Duration are one clip only. Two clips have two In points,
    /// and a field showing the first one's while writing to both would be a
    /// lie about what it edits — `reverseTimingSection()` is what a
    /// multi-clip selection gets instead.
    ///
    /// **It binds by clip ID, captured here, and reads fresh through it** —
    /// the rule every other by-id row in this panel follows
    /// (`VideoPane.transitionSection`, `DocumentPane.markerRow`), and the one
    /// place in the inspector where breaking it edits the WRONG CLIP rather
    /// than merely showing a stale number. These two fields commit on blur,
    /// and a blur can be caused by the rebuild itself: `rebuild()` removes
    /// every arranged subview, removing a field that is being typed into ends
    /// its editing session, and only then does `controlTextDidEndEditing`
    /// fire. Clicking another clip in the timeline takes that path — the
    /// timeline's content view refuses first responder, so the field keeps it
    /// while the selection changes underneath — and a `binding.primary` read
    /// inside the write closure would by then name the clip that was just
    /// clicked. `binding.snapshot.clip(id)` names the one the user typed into.
    /// Once that clip is GONE the reads fall back — 0 for the two edges, "—"
    /// for the duration — and a write still names the dead id, which the core
    /// rejects by name and `applyEdit` puts up as its message. That is loud
    /// for something rare (the clip has to be deleted while its field holds
    /// the field editor) but it is honest, and it is not the thing this rule
    /// exists to prevent, which is editing whichever clip was clicked next.
    ///
    /// The Reverse group under the edges is `reverseRows(over:mixed:)`, shared
    /// with the multi-clip section below.
    func timingSection(_ id: UInt32) -> InspectorSection {
        let binding = self.binding
        /// Read fresh on every call through the captured id, never captured
        /// itself: a trim REPLACES the clip snapshot, and the row is refreshed
        /// rather than rebuilt.
        func clip() -> ClipSnapshot? { binding.snapshot.clip(id) }
        func fps() -> Fps { binding.canvas.fps }
        func frames() -> Bool { binding.canvas.timecodeFrames }
        func duration() -> String {
            guard let clip = clip() else { return "—" }
            return ReelTime.format(clip.duration, fps: fps(), frames: frames())
        }
        let start = InspectorTimecodeField(
            read: { clip()?.start ?? 0 },
            write: { value in
                binding.apply("Trim Start", [.trimStart(clip: id, to: value)])
            },
            fps: fps, frames: frames,
            onEdit: { binding.edited() })
        start.toolTip = "Where the clip starts — trims its front edge"
        let end = InspectorTimecodeField(
            read: { clip()?.end ?? 0 },
            write: { value in
                binding.apply("Trim End", [.trimEnd(clip: id, to: value)])
            },
            fps: fps, frames: frames,
            onEdit: { binding.edited() })
        end.toolTip = "Where the clip ends — trims its back edge"

        var rows: [NSView] = [
            inspectorRow("In", [start]),
            inspectorRow("Out", [end]),
            inspectorRow("Duration", [inspectorReadout { duration() }]),
        ]
        // Reverse is a media-source op (`set_reversed`, §6); a text or shape
        // clip has no frames to turn around. The clip is re-filtered rather
        // than assumed because `allMedia` answered at BUILD time and the rows
        // read live: an empty list is no ops, which is a beep from `apply` and
        // the right answer for a clip that is no longer there. No mixed badge:
        // one clip cannot disagree with itself.
        if videoPane.allMedia {
            rows.append(
                contentsOf: reverseRows(
                    over: {
                        guard let clip = clip(), clip.source.hasSourceBound else { return [] }
                        return [clip]
                    },
                    mixed: nil))
        }
        return InspectorSection(
            id: "clip.timing", title: "Timing",
            summary: { duration() },
            defaultExpanded: false,
            rows: rows)
    }

    /// Timing for a MULTI-clip media selection: the Reverse group, and nothing
    /// else, because In, Out and Duration each describe one edge of one clip.
    ///
    /// The same section id as the single-clip Timing, so the group the user
    /// opened stays open as the selection grows and shrinks, and the same
    /// summary in the header's own vocabulary — the total of what is selected,
    /// spelled the way `ClipSelectionHeaderView` spells it.
    func reverseTimingSection() -> InspectorSection {
        let binding = self.binding
        /// Live, not captured: the rows survive a refresh, and `allMedia`
        /// answered for the selection this build saw.
        func clips() -> [ClipSnapshot] { binding.clips.filter { $0.source.hasSourceBound } }
        func total() -> String {
            let sum = clips().reduce(Ticks(0)) { $0 + $1.duration }
            let canvas = binding.canvas
            return ReelTime.format(sum, fps: canvas.fps, frames: canvas.timecodeFrames) + " total"
        }
        return InspectorSection(
            id: "clip.timing", title: "Timing",
            summary: { total() },
            defaultExpanded: false,
            rows: reverseRows(
                over: clips,
                mixed: { binding.mixed(clips()) { $0.source.isReversed } }))
    }

    /// The Reverse group — the box, the state readout and the retry button —
    /// over whatever clips the section speaks for: the one clip of a
    /// single-clip Timing, every media clip of a multi-clip one. One op per
    /// clip, all in one `apply`, so the fan-out is a single undo step.
            sections.append(videoPane.lookSection(lookGallery))
        case .sound:
            sections = [
                audioPane.volumeSection(), audioPane.fadeSection(), audioPane.duckSection(),
                // The chain's head, in signal order (spec §11 AU-54, AU-38).
                audioPane.isolationSection(), audioPane.voiceSection(),
                audioPane.channelsSection(),
                audioPane.eqSection(), audioPane.humSection(),
                audioPane.noiseSection(), audioPane.gateSection(), audioPane.levellerSection(),
                audioPane.deEsserSection(),
                audioPane.compressorSection(), audioPane.mixSection(),
                // Last in the clip's chain, so last here (spec §11 AU-26).
                audioPane.limiterSection(),
            ]
        case .clip:
            if binding.isSingle, let clip = binding.primary {
                sections.append(timingSection(clip.id))
            } else if videoPane.allMedia {
                // The half of Timing a MULTI-clip selection can still answer
                // for: Reverse is a per-clip op that fans out happily, where
                // In, Out and Duration genuinely need one clip.
                sections.append(reverseTimingSection())
            }
            if videoPane.allMedia {
                sections.append(videoPane.speedSection())
            }
            if binding.isSingle, let clip = binding.primary,
               videoPane.overlap(before: clip) != nil {
                sections.append(videoPane.transitionSection(clip.id))
            }
            if hasPixels {
                sections.append(videoPane.motionSection())
            }
        }
        // A tab that would open as a column of shut headers opens its first
        // section with no stored preference instead. `expandByDefault` defers
        // to a section the user has closed themselves, so this is a default
        // and not an override — and it is offered to each section in TURN
        // because an id can be shared (`video.speed`, `clip.timing`), and a
        // group closed once elsewhere would otherwise leave the tab shut.
        if !sections.contains(where: { $0.isExpanded }) {
            for section in sections {
                if section.expandByDefault() { break }
            }
        }
        reveal.apply(sections, action: binding.selectedAction?.id, subTab: activeSubTab.rawValue)
//! Slip and roll — spec §6 rows `slip` and `roll`.
//!
//! What separates these two from `edit_clip.rs`'s trims is that neither
//! changes how long the CUT is. A **slip** changes what a clip shows
//! without moving it: the window stays where it is on the timeline and the
//! film slides under it. A **roll** moves the frame two clips meet on
//! without moving anything else: one grows by exactly what the other loses.
//! They are what a cutter reaches for once the rough assembly is down, when
//! every following clip is already where it belongs and nothing may shift.
//!
//! Both are therefore *conservative* ops, and both are written to refuse
//! rather than approximate. A slip that has run out of source at one end
//! stops, and a slip that could not move at all is an identity — the
//! alternative is a drag that silently becomes a different, shorter edit
//! than the gesture asked for. A roll needs a hard cut to move: with a gap,
//! or with an overlap (which IS a transition, whose length is
//! `set_transition_duration`'s job), there is nothing here to roll.
//!
//! The arithmetic is `source_window.rs`'s — the three measurements of a
//! source window, the conversion into source ticks and the two last legal
//! positions all live there, and this module only clamps against them, so a
//! slip and a trim can never disagree about where a media ends.

use crate::edit_clip::clip_end;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::{source_advanced_through, timeline_to_source};
use crate::time::Ticks;

impl Project {
    /// Slides the source window under a fixed clip: what the clip shows
    /// changes, where it sits does not (spec §6).
    ///
    /// `delta` is TIMELINE ticks — the distance the gesture travelled — so
    /// the source moves by `delta × speed`, the same conversion
    /// `trim_start` makes when it advances `in`. A positive `delta` shows
    /// LATER material, which is the direction the drag reads: pulling the
    /// clip right pulls the film forward under the window.
    ///
    /// Clamped so the window stays inside the media — `in ≥ 0` at the head,
    /// `in + duration × speed ≤ media.duration` at the tail — and a slip
    /// the clamps reduce to nothing is an identity. On a RAMPED clip the
    /// delta is converted at the base rate and the tail clamp is
    /// `file − S(D)` (`last_in_point` reads S); the actions do not move
    /// (spec §11 SR-18 (d)).
    ///
    /// A `still` has one source TIME rather than a window, so it moves that
    /// instead, clamped inside the media the same way. Every other source
    /// has nothing to slip and is an `Err` under the non-media rule.
    ///
    /// **The source kind is decided FIRST**, before the delta is even
    /// measured. A text clip named for a slip is an invalid argument
    /// whatever the delta was, and letting a sub-frame delta short-circuit
    /// to an identity would answer "valid, changes nothing" to a call that
    /// was never valid — the one answer the non-media rule exists to stop
    /// the MCP agent being given.
    ///
    /// Nothing moves, so there is no overlap to check and no transition can
    /// be gained; the actions are clip-relative and stay exactly where they
    /// are.
    ///
    /// **A linked partner on an unlocked track slips with it**, by the
    /// smaller in magnitude of the two clamped amounts, so the sound stays
    /// on its picture (spec §11 AU-94).
    pub fn slip(&self, clip: u32, delta: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let delta = self.snapped(delta);
        let Some(own) = self.slip_amount(&target, delta)? else {
            return Ok(Outcome::Identity);
        };
        let partner = self
            .partner(clip)
            .filter(|p| self.track(p.track).is_some_and(|t| !t.locked))
            .cloned();
        let mut amount = own;
        if let Some(partner) = &partner {
            let theirs = self.slip_amount(partner, delta)?.unwrap_or(0);
            if theirs.abs() < amount.abs() {
                amount = theirs;
            }
        }
        if amount == 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in std::iter::once(clip).chain(partner.map(|p| p.id)) {
            if let Some(slot) = next.clip_mut(id) {
                slot.source = match &slot.source {
                    Source::Media {
                        media,
                        r#in,
                        reversed,
                    } => Source::Media {
                        media: *media,
                        r#in: r#in.saturating_add(amount),
                        reversed: *reversed,
                    },
                    Source::Still { media, at } => Source::Still {
                        media: *media,
                        at: at.saturating_add(amount),
                    },
                    other => other.clone(),
                };
            }
        }
        self.finish(next)
    }

    /// How far, in SOURCE ticks, a slip of `delta` timeline ticks moves
    /// `clip` once clamped inside its media; `None` when the move rounds to
    /// nothing before the clamp. `Err` for a source with nothing to slip,
    /// decided FIRST (the doc above).
    fn slip_amount(&self, clip: &Clip, delta: Ticks) -> Result<Option<Ticks>, String> {
        let (media, current) = match clip.source {
            Source::Media { media, r#in, .. } => (media, r#in),
            Source::Still { media, at } => (media, at),
            _ => return Err(format!("clip {} is not a media clip", clip.id)),
        };
        // Timeline ticks to source ticks, at this clip's rate. A sub-tick
        // move at a very slow speed rounds to nothing, which is a refusal
        // and not an edit.
        let moved_by = timeline_to_source(delta, clip.speed);
        if moved_by == 0 {
            return Ok(None);
        }

        // The last legal position of what the clip shows: a window is
        // pushed against the tail of the file, a still stops one frame
        // short of it. Both are `source_window.rs`'s, which is also where
        // the reasons for the two shapes are written down.
        let media = self.require_media(media)?;
        let last = match clip.source {
            Source::Still { .. } => self.last_still_time(media),
            _ => self.last_in_point(clip, media),
        };
        let slipped = current.saturating_add(moved_by).clamp(0, last);
        Ok(Some(slipped.saturating_sub(current)))
    }

    /// Moves a hard cut: this clip's start and its predecessor's end both
    /// become `to`, and nothing else in the timeline moves (spec §6).
    ///
    /// The predecessor is the clip on the same track that ends EXACTLY at
    /// this clip's start. With no such clip the op refuses, naming the
    /// track and the start (spec §11 #88) — a gap has no cut to roll, and an
    /// overlap is a transition whose length `set_transition_duration` owns.
    ///
    /// `to` is clamped four ways, one pair per side: each clip keeps at
    /// least one frame, this clip may only reach back as far as its own
    /// source head allows (it grows at the FRONT, with front-trim
    /// semantics, so `in` follows), and the predecessor may only reach
    /// forward as far as its remaining source allows (it grows at the END,
    /// a plain end trim, so its `in` does not move). A `to` the clamps
    /// leave equal to the current cut is an identity, and so is a pair of
    /// clamps that cross — a cut with no legal position is not one this op
    /// can move.
    ///
    /// On a RAMPED clip this clip's `in` advances through its map, and the
    /// cut is held where it still fits its media (`front_edge_held`); the
    /// predecessor's bound reads its map on past its end (spec §11 SR-18
    /// (a), (c)).
    ///
    /// Neither clip's outer edge moves, so the pair still abuts exactly and
    /// no transition can be gained; the actions on both are clip-relative
    /// and stay where they are, as they do for a trim. This clip's
    /// `text.words` are rebased by the move, as `trim_start` rebases them
    /// (spec §11, W-3): a word stays on the speech it times. Its
    /// `graphic.in` advances by the move as `trim_start`'s does, and the
    /// predecessor's `length` is untouched (road map 10's G-9).
    ///
    /// Without `alone`, a linked partner whose start is this clip's and
    /// which has a hard-cut predecessor of its own is rolled to the same
    /// `to` after it (spec §11 AU-93, `carried_edge`); with it, the clip's
    /// cut moves alone.
    pub fn roll(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        let hard_cut = |partner: &Clip| {
            self.clips_on_track(partner.track)
                .iter()
                .any(|c| c.id != partner.id && clip_end(c) == partner.start)
        };
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start && hard_cut(partner),
            |project, id| project.roll_one(id, to),
        )
    }

    fn roll_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Some(previous) = self
            .clips_on_track(target.track)
            .into_iter()
            .find(|c| c.id != target.id && clip_end(c) == target.start)
            .cloned()
        else {
            return Ok(Outcome::Refused(format!(
                "no clip on track {} ends where clip {clip} begins ({}), so there is no cut \
                 to roll",
                target.track, target.start
            )));
        };

        let frame = self.frame();
        let mut earliest = previous.start.saturating_add(frame);
        let mut latest = clip_end(&target).saturating_sub(frame);
        if let Some(start) = self.earliest_start_on_grid(&target) {
            earliest = earliest.max(start.max(0));
        }
        if let Some(end) = self.latest_end_on_grid(&previous) {
            latest = latest.min(end);
        }
        // The two source bounds arrive on the grid (`source_window.rs`
        // snaps each inward, and this pair is where that rule came from),
        // but the one-frame bounds are measured from the clips' own starts,
        // which a hand-written document may put off it. So both are snapped
        // INWARD again — up at the bottom, down at the top — and the cut
        // lands on a frame that is still inside the source both clips have.
        let earliest = self.snapped_up(earliest);
        let latest = self.snapped_down(latest);
        if earliest > latest {
            return Ok(Outcome::Identity);
        }
        let to = self.snapped(to).clamp(earliest, latest);
        // A ramped target's front edge is held where it still fits its
        // media, as `trim_start`'s is (spec §11 SR-18 (c)).
        let to = self.front_edge_held(&target, to);
        if to == target.start {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, to.saturating_sub(target.start));
        moved.graphic = graphic_advanced(target.graphic.as_ref(), to.saturating_sub(target.start));
        moved.start = to;
        moved.duration = clip_end(&target).saturating_sub(to);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, to.saturating_sub(target.start));
        }

        let mut grown = previous.clone();
        grown.duration = to.saturating_sub(previous.start);

        // The clamps make this unreachable for the pair itself; it is here
        // because every placement op checks, and because a track that
        // already held something the rule dislikes should not have it made
        // worse by an edit that thought it was safe.
        if let Err(why) =
            self.check_overlap_rule(&[moved.clone(), grown.clone()], target.track, &[])
        {
            return Ok(Outcome::Refused(why));
        }

        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(target.id) {
            *slot = moved;
        }
        if let Some(slot) = next.clip_mut(previous.id) {
            *slot = grown;
        }
        self.finish(next)
    }
}

/// The two drags are begun here rather than in `TimelineView.swift`, which is
/// frozen at wiring — the same split `TimelineClipDrawing.swift` and
/// `MediaPane.swift`'s drop targets already use — so the view keeps one stored
/// property per session and one line per dispatcher.
extension TimelineView {

    /// ⌥⇧ on a clip body: slip. Locked tracks are not draggable at all, so
    /// this refuses there exactly as `beginClipDrag` does.
    ///
    /// Deliberately does NOT touch the selection. ⌥⇧ arrives at `selectClip`
    /// as "toggle membership", and a slip is a gesture on the clip under the
    /// pointer whatever else is selected — so `beginGesture` routes here
    /// before the selection is consulted.
    func beginSlip(_ id: UInt32, at point: CGPoint, flags: NSEvent.ModifierFlags) {
        guard let clip = snapshot.clip(id),
              let index = snapshot.trackIndex(of: clip.track),
              !snapshot.tracks[index].locked
        else { return }
        slip = SlipSession(clip: id, grabTime: layout.time(atX: point.x))
        onLiveBegin?()
    }

    /// ⌥⇧ on a clip edge: roll the cut that edge sits on.
    ///
    /// Which cut that is depends on which edge was grabbed, and the op always
    /// names the clip on the cut's RIGHT: the start edge rolls this clip
    /// against its predecessor, the end edge rolls this clip's successor
    /// against it. With no clip on the other side of the edge — a gap, or an
    /// overlap, which is a transition — there is no cut here and no session
    /// starts, so the drag is inert rather than quietly doing a trim.
    func beginRoll(_ id: UInt32, edge: TimelineEdge, flags: NSEvent.ModifierFlags) {
        guard let clip = snapshot.clip(id),
              let index = snapshot.trackIndex(of: clip.track),
              !snapshot.tracks[index].locked
        else { return }
        let neighbours = snapshot.clips.filter { $0.track == clip.track && $0.id != id }
        let (left, right): (ClipSnapshot, ClipSnapshot)
        switch edge {
        case .start:
            guard let previous = neighbours.first(where: { $0.end == clip.start }) else { return }
            (left, right) = (previous, clip)
        case .end:
            guard let next = neighbours.first(where: { $0.start == clip.end }) else { return }
            (left, right) = (clip, next)
        }
        let frame = max(snapshot.canvas.fps.frameDuration, 1)
        dragSnapper = makeSnapper(excluding: [left.id, right.id], suppressed: flags.contains(.command))
        roll = RollSession(
            clip: right.id, alone: clip.isLinkedSound,
            earliest: left.start + frame, latest: right.end - frame,
            time: right.start)
        onLiveBegin?()
    }

    /// Double-click in empty lane space: close the gap it landed in. The core
    /// finds the gap's bounds and beeps through `applyEdit` when there is
    /// none to close, so the view only has to name the track.
    func closeGap(row: Int, at time: Ticks) {
        guard let track = track(atRow: row) else { return }
        onEdit?("Close Gap", [.closeGap(track: track.id, at: max(time, 0))])
    }

}

extension EditorViewController {

    // MARK: - Nudging

    /// `,` and `.`, ×10 with ⇧ — the selection moved by whole frames.
    ///
    /// A plain `move_clip`, so the overlap rule refuses it exactly as a drag
    /// to the same place would, and `applyEdit` beeps for us.
    func nudgeSelection(frames: Int) {
        guard let document = document, !document.selection.isEmpty else {
            NSSound.beep()
            return
        }
        let frame = max(document.editedProject.snapshot.canvas.fps.frameDuration, 1)
        document.applyEdit(
            "Nudge Clips",
            .moveClip(clips: Array(document.selection), delta: Ticks(frames) * frame))
    }

    // MARK: - Closing a gap

    /// Clip ▸ Close Gap: the gap under the playhead, on the selected clip's
    /// track — or, with nothing selected, the front-most track, which is
    /// where the eye goes and where `EditorViewController+AddClips` puts a
    /// new clip for the same reason.
    func closeGapAtPlayheadCommand() {
        guard let document = document, let track = targetTrack else {
            NSSound.beep()
            return
        }
        document.applyEdit("Close Gap", .closeGap(track: track, at: document.playhead))
    }
    var currentTrack: TrackSnapshot? {
        guard let document = document else { return nil }
        let snapshot = document.editedProject.snapshot
        if let clip = selectedClips.first, let track = snapshot.track(clip.track) { return track }
        return snapshot.tracks.last
    }

    /// Clips that both are selected and cross the playhead — what a
    /// playhead-relative op (freeze frame, trim to playhead) can act on.
    private var clipsUnderPlayhead: [ClipSnapshot] {
        guard let document = document else { return [] }
        let now = document.playhead
        return selectedClips.filter { $0.contains(now) }
    }

    // MARK: - Clip commands (spec §6, the keys of §9)

    /// ⌘T. With nothing selected the core splits every unlocked clip under
    /// the playhead, which is what `clips: nil` means.
    func splitAtPlayheadCommand() {
        guard let document = document else { return }
        let ids = document.selection
        document.applyEdit(
            "Split", .split(clips: ids.isEmpty ? nil : Array(ids), at: document.playhead))
    }

    /// W / E. Every selected clip is offered to the core; the ones the
    /// playhead is not inside are refused, and a wholly refused batch beeps.
    /// A linked sound half trims alone, as its edge's drag does (spec §11
    /// AU-93).
    func trimToPlayhead(_ edge: TimelineEdge) {
        guard let document = document else { return }
        let now = document.playhead
        let ops = clipsUnderPlayhead.map { clip in
            edge == .start
                ? ReelOp.trimStart(clip: clip.id, to: now, alone: clip.isLinkedSound)
                : ReelOp.trimEnd(clip: clip.id, to: now, alone: clip.isLinkedSound)
        }
        guard !ops.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit(edge == .start ? "Trim Start" : "Trim End", ops)
    }

    /// ⌫ — removes the selection and leaves the gap, or LIFTS the in/out
    /// range when nothing is selected (spec §9).
    ///
    /// The pairing with ⌘⌫ below is deliberate and complete: each key does
    /// the same thing to a selection and to a range, and the difference
    /// between the two keys is only whether the hole closes.
    func deleteSelection() {
        guard let document = document else { return }
        // Words selected in the Transcript tab ripple out (spec §11 TX-31).
        if transcriptHoldsWords { return deleteTranscriptWords() }
        // With an action selected ⌫ removes IT, not its clip (spec §9).
        if document.selectedActionSnapshot != nil {
            removeSelectedActionCommand()
            return
        }
        if document.selection.isEmpty {
            guard let range = document.inOutRange, range.end > range.start else {
                NSSound.beep()
                return
            }
            document.applyEdit("Lift", .liftRange(from: range.start, to: range.end))
            return
        }
        document.applyEdit("Delete", .delete(clips: Array(document.selection)))
    }

    /// ⌘⌫ — the selection, or the in/out range when nothing is selected
    /// (spec §9).
    func rippleDeleteSelection() {
        guard let document = document else { return }
        if transcriptHoldsWords { return deleteTranscriptWords() }
        if document.selection.isEmpty {
            guard let range = document.inOutRange, range.end > range.start else {
                NSSound.beep()
                return
            }
            document.applyEdit(
                "Ripple Delete", .rippleDeleteRange(from: range.start, to: range.end))
            return
        }
        document.applyEdit("Ripple Delete", .rippleDelete(clips: Array(document.selection)))
    }

    /// ⌘D — copies land after the originals' span; ⌥-dragging then moves
    /// them, which is the same op with a `move_clip` behind it.
    func duplicateSelection() {
        guard let document = document, !document.selection.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit("Duplicate", .duplicate(clips: Array(document.selection)))
    }

    /// ⇧⌘F — one still clip filling a gap opened at the playhead.
    func freezeSelection() {
        guard let document = document, let clip = clipsUnderPlayhead.first else {
            NSSound.beep()
            return
        }
        document.applyEdit("Freeze Frame", .freezeFrame(clip: clip.id, at: document.playhead))
    }

    /// ⌥⌘D — the audio moves to its own clip on the track below.
    func detachSelectionAudio() {
        guard let document = document, !selectedClips.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit("Detach Audio", selectedClips.map { .detachAudio(clip: $0.id) })
    }

    /// ⇧⌥⌘D — Clip ▸ Attach Audio and the Mix section's button: each linked
    /// pair the selection touches merges back into one clip (spec §11 AU-95).
    @objc func attachAudio(_ sender: Any?) { attachSelectionAudio() }

    /// One `attach_audio` per PAIR, so a selection holding both halves of a
            return .trimStart(clip: clip, to: min(time, originalEnd - frame), alone: alone)
        case .end:
            let to = max(time, originalStart + frame)
            return isRateStretch
                ? .rateStretch(clip: clip, toEnd: to)
                : .trimEnd(clip: clip, to: to, alone: alone)
        }
    }

    mutating func update(time: Ticks, snapper: TimelineSnapper) {
        let resolved = snapper.resolve(time)
        // Clamped here as well as in the core: the preview must not show an
        // inverted bar for the ticks the core is busy refusing.
        switch edge {
        case .start:
            self.time = max(0, min(resolved.time, originalEnd - frame))
        case .end:
            self.time = max(resolved.time, originalStart + frame)
        }
        guide = resolved.guide
        didMove = true
    }
}

// MARK: - The edge moves

/// ⌥⇧-dragging a clip's BODY: the source slides under a fixed clip
/// (spec §6 `slip`).
///
/// The op's `delta` is the TOTAL travel since mouse-down, not this tick's
/// increment, because `updateLiveEdit` re-applies against the handle the
/// gesture started from. It is also deliberately unsnapped: the thing being
/// moved is inside the media, where the timeline's candidates — other
/// clips' edges, the markers, the playhead — mean nothing. The core rounds
/// it to the frame grid, so the film still steps a frame at a time.
struct SlipSession {
    let clip: UInt32
    /// Time under the pointer at mouse-down, so the film keeps pace with
    /// the cursor.
    let grabTime: Ticks

    var delta: Ticks = 0
    var didMove = false

    var op: ReelOp { .slip(clip: clip, delta: delta) }

    mutating func update(time: Ticks) {
        delta = time - grabTime
        didMove = true
    }
}

