//! Cutting one clip in two — `split_clip` and the two helpers only it has
//! ever needed, `state_patch` and `narrow_to`.
//!
//! Cut out of `edit_clip.rs` in road map 5's E2, which owed it a rule about
//! `video.motion` and found a 1171-line file, and cut HERE because a split
//! is not a placement: every other op in `edit_clip.rs` decides where a
//! clip sits or what it is made of, while this one has to decide what the
//! SECOND clip inherits — its base props from the evaluation at the cut, so
//! the join is invisible; the actions that had not finished, rebased to its
//! own clip time, with a straddled one narrowed to the keys it animated;
//! and, since E2, the halves of a preset anchored to the clip's two ends.
//! The cursor's `smoothing` and `hide_idle` are the one exception to "the
//! evaluation at the cut": the second half keeps the original's base values
//! (spec §11 CU-30).
//! That inheritance question is the whole of this module and appears
//! nowhere else in the crate.
//!
//! Every splitter in the crate routes here — `split_clips`,
//! `split_under_playhead`, `clear_range` (so `ripple_delete_range(s)` and
//! `lift_range`), `insert_clip`, `overwrite_clip`, `freeze_frame` and
//! `keep_range` — so a rule stated once is a rule they all obey. It is a
//! free function taking `&mut Project` rather than a `Project` method for
//! the reason it always was: it is called mid-edit on a clone the caller is
//! still assembling, after `finish` would be too late and before it has
//! anything to hand back.

use serde_json::Value;

use crate::actions::{self, Evaluated, MAX_PATCH_DEPTH};
use crate::cursor_props::with_base_cursor;
use crate::edit_clip::clip_end;
use crate::model::{Action, Curve, Project, VideoProps};
use crate::model_words::{rebase_words, token_count};
use crate::recipe_graphic::{effective_length, graphic_advanced};
use crate::source_window::source_advanced_through;
use crate::speed_map::{end_speed, SpeedMap};
use crate::time::Ticks;

/// The evaluated state as an action-style patch object, so `split` can hand
/// the first half of a straddled action the state it must reach. A
/// graphic's evaluated props go in as `graphic.props` (G-34), which
/// [`narrow_to`] narrows to the props the action named, carrying its
/// `kinds` through untouched.
pub(crate) fn state_patch(evaluated: &Evaluated) -> Value {
    let mut out = serde_json::Map::new();
    // `video_json`: a tone key at exactly 0 at the cut must still be here,
    // or `narrow_to` puts back the action's END value (spec §11 GR-2).
    out.insert("video".to_string(), actions::video_json(&evaluated.video));
    out.insert("audio".to_string(), actions::to_json(&evaluated.audio));
    if let Some(text) = &evaluated.text {
        out.insert("text".to_string(), actions::to_json(text));
    }
    if let Some(graphic) = &evaluated.graphic {
        let mut props = serde_json::Map::new();
        props.insert("props".to_string(), Value::Object(graphic.props.clone()));
        out.insert("graphic".to_string(), Value::Object(props));
    }
    Value::Object(out)
}

/// `state` narrowed to the keys `shape` mentions — the minimal patch with
/// the same reach as the original. Keeping the shape means a split action's
/// first half animates exactly the fields the whole action animated, rather
/// than pinning every property of the clip.
pub(crate) fn narrow_to(state: &Value, shape: &Value, depth: u32) -> Value {
    let (Value::Object(from), Value::Object(keys)) = (state, shape) else {
        return shape.clone();
    };
    if depth >= MAX_PATCH_DEPTH {
        return shape.clone();
    }
    let mut out = serde_json::Map::new();
    for (key, sub) in keys {
        match from.get(key) {
            Some(value) if value.is_object() && sub.is_object() => {
                out.insert(key.clone(), narrow_to(value, sub, depth + 1));
            }
            Some(value) => {
                out.insert(key.clone(), value.clone());
            }
            // A key the state does not have (an unknown patch key): carry
            // the original through untouched, exactly as evaluation would.
            None => {
                out.insert(key.clone(), sub.clone());
            }
        }
    }
    Value::Object(out)
}

/// Cuts `clip_id` in two at project time `at`, in place. Returns false —
/// and changes nothing — when `at` is not strictly inside the clip, which
/// is the spec's refusal.
///
/// The second clip's BASE props are the evaluated state at the cut, so the
/// join is invisible; its actions are the ones that had not finished,
/// rebased to its own clip time. A graphic's `props` are the evaluated
/// ones, and a straddled action's first half ends at them (G-34).
pub(crate) fn split_clip(project: &mut Project, clip_id: u32, at: Ticks) -> bool {
    let Some(original) = project.clip(clip_id).cloned() else {
        return false;
    };
    let clip_t = at.saturating_sub(original.start);
    if clip_t <= 0 || clip_t >= original.duration {
        return false;
    }
    let state = project.evaluate_clip(&original, clip_t);
    let patch_source = state_patch(&state);
    // The ORIGINAL's map, read once: a ramped clip's halves meet at the
    // source it read by the cut (spec §11 SR-18 (e)). `None` for a
    // constant clip, which takes the one-rate path unchanged.
    let map = SpeedMap::of(&original);
    // Measured on the ORIGINAL, so a null `length` is `in` plus the WHOLE
    // duration, not the half either piece keeps.
    let pinned = effective_length(&original);

    let mut second = original.clone();
    second.id = project.allocate_id();
    second.start = at;
    second.duration = clip_end(&original).saturating_sub(at);
    // The cut consumes `clip_t` of timeline, which is `clip_t * speed` of
    // source — round(S(cut)) on a ramped clip, whose second half starts at
    // the rate in force there; a still's frozen frame and the sourceless
    // kinds do not move, which is `source_advanced_through`'s own rule.
    second.source = source_advanced_through(&original, clip_t);
    if let Some(map) = &map {
        second.speed = map.rate_at(clip_t);
    }
    // A graphic's own timeline (road map 10's G-9): the second half starts
    // `clip_t` further into it, and BOTH halves keep the original's length,
    // so the join is invisible and neither half's outro moves — the first
    // half's `in + duration` would otherwise be only the head.
    second.graphic = graphic_advanced(state.graphic.as_ref(), clip_t);
    if let Some(graphic) = second.graphic.as_mut() {
        graphic.length = pinned;
    }
    // Presence of a group is a fact about the clip, so an audio-only clip
    // stays audio-only; only the values come from the evaluation.
    // The cursor's `smoothing` and `hide_idle` stay the original's BASE
    // values, never an end's (spec §11 CU-30).
    second.video = original
        .video
        .as_ref()
        .map(|_| with_base_cursor(state.video.clone(), original.video.as_ref()));
    second.audio = original.audio.map(|_| state.audio);
    second.text = state.text.clone();
    second.shape = original.shape.clone();
    // The transition covers the join with the PREVIOUS clip, which is still
    // the first half's business (spec §6).
    second.transition_in = None;

    // A preset anchored to the clip's two ends, cut in two: the FIRST half
    // keeps the entrance and gives up the exit, the SECOND keeps the exit
    // and gives up the entrance (format version 8). Carrying both to both
    // halves — which is what a bare clone does, and what `text.animation`
    // had done since format version 5 — makes the first half leave at the
    // cut and the second arrive again there, so a join a viewer is not
    // supposed to see becomes the most visible thing in the shot. Neither
    // half's kept slot is rescaled: a preset is a duration, and the tent
    // rule (`motion.rs`) is what handles one now too long for the half it
    // landed on.
    //
    // Both are normalised to the field's "nothing" — `None` for a motion
    // whose slots are all empty, `None` for an animation with no ramp at
    // either end — so a split leaves one spelling of it, `edit_props.rs`'s
    // patch path's rule applied to the other writer that can produce one.
    let motion_of = |video: &mut Option<VideoProps>, keep_in: bool| {
        if let Some(video) = video.as_mut() {
            if let Some(motion) = video.motion.as_mut() {
                if keep_in {
                    motion.out = None;
                } else {
                    motion.r#in = None;
                }
                if motion.is_empty() {
                    video.motion = None;
                }
            }
        }
    };
    motion_of(&mut second.video, false);
    // The second half's word timings (format version 9, spec §11 W-3). A
    // word is anchored to its speech, so the second half keeps ALL of them,
    // rebased by the cut: a negative start means "already said" and the
    // split is invisible. The first half is untouched — its clip time did
    // not move.
    //
    // Except in one case, and only on this half: the text stored here is
    // the EVALUATED text, so a finished action whose end patch switched
    // `content` (which `set_action_end` lets through, where it refuses
    // `words`) lays a new content over the base `words`. A half stored with
    // that mismatch would be a clip the patch door refuses on every later
    // `set_text` or `paste_attributes` — even one that only changes the
    // colour — until the caller sent `words: []`. A half is a clip the door
    // must accept again, so a count that no longer matches stores `[]`: the
    // page draws static, which is what the recipe already drew for it.
    if let Some(text) = second.text.as_mut() {
        if !text.words.is_empty() && token_count(&text.content) != text.words.len() {
            text.words = Vec::new();
        } else {

            }
        }
    }

    // MARK: - Targets

    /// Whether `clip` is a target: a media clip whose media is a video with
    /// pictures, its picture switched on.
    static func qualifies(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard case .media(let id, _, _) = clip.source, clip.enabled.video,
            let media = snapshot.media(id)
        else { return false }
        return media.kind == .video && media.hasVideo
    }

    /// Every target on an unlocked track: the tool's `clips` left out.
    static func unlockedCandidates(in snapshot: ProjectSnapshot) -> [UInt32] {
        snapshot.clips.filter { clip in
            snapshot.track(clip.track).map { !$0.locked } == true && qualifies(clip, in: snapshot)
        }.map(\.id)
    }

    /// The targets among `ids` in `project` (the edited, scoped one), and the
    /// ids skipped.
    static func targets(_ ids: [UInt32], in project: ReelProject)
        -> (targets: [Target], skipped: [UInt32])
    {
        let snapshot = project.snapshot
        var targets: [Target] = []
        var skipped: [UInt32] = []
        for id in ids where !targets.contains(where: { $0.clip.id == id }) {
            guard let clip = snapshot.clip(id), qualifies(clip, in: snapshot),
                let media = snapshot.media(for: clip)
            else {
                if !skipped.contains(id) { skipped.append(id) }
                continue
            }
            targets.append(Target(
                clip: clip, media: media,
                times: AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(id))))
        }
        return (targets, skipped)
    }

    // MARK: - Wants

    /// The requests the targets still need, one per media in first-target
    /// order: each target's window asked of the store, a media's misses
    /// merged into one request. Empty when every window is a hit. Main
    /// thread; throws `analysisRequest`'s errors.
    static func wants(_ targets: [Target], in document: ProjectDocument) throws -> [Want] {
        var order: [UInt32] = []
        var groups: [UInt32: [Target]] = [:]
        for target in targets {
            if groups[target.media.id] == nil { order.append(target.media.id) }
            groups[target.media.id, default: []].append(target)
        }
        var wants: [Want] = []
        for id in order {
            let group = groups[id] ?? []
            guard let media = group.first?.media else { continue }
            let spans = group.map(\.times.window)
            var misses: [AnalysisRequest] = []
            for window in spans {
                if let request = try document.analysisRequest(
                    kind: .shots, media: media, window: window)
                {
                    misses.append(request)
                }
            }
            guard let first = misses.first else { continue }
            let request = AnalysisRequest(
                kind: first.kind, cacheDir: first.cacheDir, media: first.media, url: first.url,
                stamp: first.stamp, input: first.input,
                ranges: AnalysisStore.merged(misses.flatMap(\.ranges)))
            wants.append(Want(media: media, request: request))
        }
        return wants
    }

    // MARK: - The plan

    /// The ops and what they cut, from the store. Main thread. Throws
    /// `notCached` when a window misses again, `ceiling` when the splits
    /// would pass the clip ceiling, and `analysisRequest`'s errors.
    static func plan(_ targets: [Target], in document: ProjectDocument) throws -> Plan {
        if let missing = try wants(targets, in: document).first {
            throw Refusal.notCached(missing.media.id)
        }
        guard let cacheDir = document.cacheDirectory else {
            throw ProjectDocument.AnalysisRequestError.noCache
        }
        let edited = document.editedProject.snapshot
        let fps = edited.canvas.fps
        let frame = fps.frameDuration
        var records: [UInt32: [AnalysisShots.Record]] = [:]
        var ops: [ReelOp] = []
        var cuts: [(clip: UInt32, at: [Ticks])] = []
        var added = 0
        for target in targets {
            let clip = target.clip
            let grid = AnalysisGrid(media: target.media)
            let held = records[target.media.id] ?? AnalysisShots.decode(
                AnalysisStore.readPayload(
                    .shots, media: target.media.id, file: AnalysisShots.payloadName,
                    in: cacheDir) ?? Data(),
                count: grid.count)
            records[target.media.id] = held
            guard let window = grid.indices(
                from: target.times.window.lowerBound, to: target.times.window.upperBound)
            else { continue }
            var times = Set<Ticks>()
            for k in AnalysisShots.cuts(held, in: window) {
                let time = target.times.clipTime(ofSource: held[k].pts)
                let t = ReelTime.snapToFrame(clip.start + time, fps: fps)
                if t - clip.start <= frame || clip.end - t <= frame { continue }
                times.insert(t)
            }
            guard !times.isEmpty else { continue }
            let partner = clip.linked.flatMap { edited.clip($0) }.flatMap { other in
                other.linked == clip.id && edited.track(other.track).map { !$0.locked } == true
                    ? other : nil
            }
            for t in times {
                added += 1
                if let partner, partner.start < t, t < partner.end { added += 1 }
            }
            let sorted = times.sorted()
            cuts.append((clip: clip.id, at: sorted))
            ops += sorted.reversed().map { ReelOp.split(clips: [clip.id], at: $0) }
        }
        let room = Int(RC_MAX_CLIPS) - clipCount(document.project.snapshot)
        guard added <= room else { throw Refusal.ceiling(added: added, room: max(0, room)) }
        return Plan(ops: ops, cuts: cuts, added: added)
    }

    /// Every clip the core's `check_caps` counts: the top level's and every
    /// nest's. Only ever handed the UNSCOPED project's snapshot.
    static func clipCount(_ snapshot: ProjectSnapshot) -> Int {
        snapshot.clips.count + snapshot.nests.reduce(0) { $0 + $1.clips.count }
    }
}
import AppKit

/// Clip ▸ Split at Shot Changes (spec §11 CJ-28, CJ-29; road map
/// "creator-jobs" CJ2b) — the menu half of `split_at_shots`. The planner is
/// `ShotSplit`, which the tool calls too; this file is the door: the
/// selection's targets, the Analyzing sheet when the shots analysis misses
/// the cache, and the edit.
///
/// With every window cached the split lands at once, in the menu's event
/// (`applyEdit`). Otherwise the sheet makes what is missing; its hand-back
/// is not an AppKit event, so the split goes through `performGroupedEdit`
/// (app/CLAUDE.md's undo pitfall, `finishSynchronizeAudio`'s shape), and
/// only onto the project handle and scope the press read. Nothing to split,
/// no window or a sheet already up beep; a refusal beeps and puts its
/// sentence at the inspector's foot (spec §11 CI-10).
extension EditorViewController {

    @objc func splitAtShotChanges(_ sender: Any?) {
        guard let document, let window = view.window, window.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let targets = ShotSplit.targets(selectedClips.map(\.id), in: document.editedProject)
            .targets
        guard !targets.isEmpty else {
            NSSound.beep()
            return
        }
        let wants: [ShotSplit.Want]
        do {
            wants = try ShotSplit.wants(targets, in: document)
        } catch {
            refuseShotSplit(error.localizedDescription, document: document)
            return
        }
        guard !wants.isEmpty else {
            commitShotSplit(targets, document: document, grouped: false)
            return
        }
        let asked = document.project
        let scope = document.scope
        let rows = wants.map { AnalyzingSheetController.Row(name: $0.media.name, request: $0.request) }
        presentAsSheet(
            AnalyzingSheetController(
                document: document, command: ShotSplit.actionName, rows: rows
            ) { [weak self, weak document] outcome in
                guard let self, let document else { return }
                self.finishShotSplit(
                    outcome, targets: targets, asked: asked, scope: scope, document: document)
            })
    }

    /// The Analyzing sheet's answer: refused when the document's project or
    /// scope is no longer the one the press read; a failed analysis named;
    /// else the plan, as one grouped step.
    private func finishShotSplit(
        _ outcome: AnalyzingSheetController.Outcome, targets: [ShotSplit.Target],
        asked: ReelProject, scope: UInt32?, document: ProjectDocument
    ) {
        guard document.project === asked, document.scope == scope else {
            refuseShotSplit(
                "the project changed while \(ShotSplit.actionName) was analyzing, so nothing "
                    + "was split. Choose \(ShotSplit.actionName) again.", document: document)
            return
        }
        switch outcome {
        case .failed(let name, let why):
            refuseShotSplit("The shots analysis of “\(name)” failed: \(why).", document: document)
        case .landed:
            commitShotSplit(targets, document: document, grouped: true)
        }
    }

    /// Plans from the store and applies: in the menu's event when `grouped`
    /// is false, else as one explicit undo group. No cut beeps.
    private func commitShotSplit(
        _ targets: [ShotSplit.Target], document: ProjectDocument, grouped: Bool
    ) {
        let plan: ShotSplit.Plan
        do {
            plan = try ShotSplit.plan(targets, in: document)
        } catch {
            refuseShotSplit(error.localizedDescription, document: document)
            return
        }
        guard !plan.ops.isEmpty else {
            NSSound.beep()
            return
        }
        if grouped {
            document.performGroupedEdit(ShotSplit.actionName, plan.ops)
        } else {
            document.applyEdit(ShotSplit.actionName, plan.ops)
        }
    }

    /// A beep and the sentence at the inspector's foot.
    private func refuseShotSplit(_ reason: String, document: ProjectDocument) {
        NSSound.beep()
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: ["refusal": ReelRefusal(op: "split_at_shots", reason: reason)])
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case;
    /// nil for any other action. On when a selected clip is a target.
    func validateShotSplitAction(_ action: Selector) -> Bool? {
        guard action == #selector(splitAtShotChanges(_:)) else { return nil }
        guard let snapshot = document?.editedProject.snapshot else { return false }
        return selectedClips.contains { ShotSplit.qualifies($0, in: snapshot) }
    }
}
