        var pts: Int64
        var d1: Float
        var d2: Float

        static let empty = Record(pts: -1, d1: 0, d2: 0)
        var holdsFrame: Bool { pts >= 0 }
    }

    // MARK: - The signature

    /// 64 counts of a picture's colours by their top two bits.
