//! Ripple, insert time, range delete, lift, close gap and freeze frame —
//! spec §6 rows `ripple_delete`, `ripple_delete_range`,
//! `ripple_delete_ranges`, `lift_range`, `close_gap`, `insert_time` and
//! `freeze_frame`, and the §11 decisions they implement.
//!
//! What separates these from `edit_clip.rs`'s ops is that they move
//! material they were never given: closing or opening a hole in the cut
//! shifts clips the caller did not name, on tracks the caller did not name.
//! Three rules run through all of it (spec §11):
//!
//! 1. **Ripple is timeline-wide.** A ripple shifts every UNLOCKED track,
//!    not only the tracks the removed clips were on — that is the one
//!    behaviour that keeps a music bed in sync with the
//!    picture it was cut to.
//! 2. **Locked tracks never move.** Locking a track is how the user says
//!    "this stays where it is", and it is the only protection from a
//!    timeline-wide shift.
//! 3. **Straddling clips stay put.** A clip that covers a boundary is not
//!    cut by a shift; only clips that begin at or after the boundary move.
//!    Clips never push each other, and a shift never splits anything the
//!    user did not ask to split.
//!
//! Everything here is composed from the primitives in `edit_clip.rs` —
//! `split_clips`, `split_under_playhead`, `snapped`, `finish` — rather than
//! restating them, so a split made by a range delete is the same split ⌘T
//! makes.

use crate::cursor_props::with_base_cursor;
use crate::edit_clip::clip_end;
use crate::model::{Clip, Enabled, Project, Source, VideoProps};
use crate::outcome::Outcome;
use crate::source_window::source_read_by;
use crate::time::{Ticks, TIMESCALE};

/// Default freeze length (spec §6). Two seconds is long enough for a hold
/// to read as deliberate and short enough that the user trims it rather
/// than deletes it.
const DEFAULT_FREEZE_DURATION: Ticks = 2 * TIMESCALE;

/// A half-open span of project time a ripple removes.
#[derive(Debug, Clone, Copy)]
struct Span {
    start: Ticks,
    end: Ticks,
}

/// The spans merged into disjoint ones, ascending.
///
/// Adjacent spans merge as well as overlapping ones: two clips that meet at
/// a cut leave ONE hole, and shifting twice by two lengths is the same as
/// shifting once by their sum only when the boundaries are handled in one
/// piece. Empty spans are dropped — a zero-length hole moves nothing.
fn union(mut spans: Vec<Span>) -> Vec<Span> {
    spans.sort_by_key(|s| (s.start, s.end));
    let mut out: Vec<Span> = Vec::new();
    for span in spans {
        if span.end <= span.start {
            continue;
        }
        match out.last_mut() {
            Some(last) if span.start <= last.end => last.end = last.end.max(span.end),
            _ => out.push(span),
        }
    }
    out
}

/// THE locked-track refusal, written once (spec §5.5, deepening D2·3).
///
/// Three ops refuse over a lock — `close_gap` and `insert_clip` on their
/// destination track, `add_transition`'s ripple form on the incoming clip's
/// track — and each has its own consequence to report, so `what` is the
/// clause after the comma. What every caller acts on is the same: the id of
/// the track to unlock.
pub(crate) fn locked_track(track: u32, what: &str) -> String {
    format!("track {track} is locked, so {what}")
}

/// The ids of every track a timeline-wide shift may touch.
pub(crate) fn unlocked_tracks(project: &Project) -> Vec<u32> {
    project
        .tracks
        .iter()
        .filter(|t| !t.locked)
        .map(|t| t.id)
        .collect()
}

/// What a shift at `from` moves: every clip on an unlocked track starting
/// at or after `from` (rule 3: a straddler stays), and each one's linked
/// partner on an unlocked track, whatever its start (spec §11 AU-91).
pub(crate) fn shifted(project: &Project, from: Ticks) -> Vec<u32> {
    let unlocked = unlocked_tracks(project);
    let mut out: Vec<u32> = Vec::new();
    for clip in project.clips.iter().filter(|c| c.start >= from) {
        let partner = project.partner(clip.id).map(|p| (p.id, p.track));
        for (id, track) in [Some((clip.id, clip.track)), partner].into_iter().flatten() {
            if unlocked.contains(&clip.track) && unlocked.contains(&track) && !out.contains(&id) {
                out.push(id);
            }
        }
    }
    out
}

/// THE shift primitive: exactly [`shifted`]'s clips move by `delta`, in
/// place. Ripple, the range form and insert time differ only in what they
/// compute for `from` and `delta`. `Some` refusal, nothing moved, when a
/// partner leading its clip would start before 0; the caller answers it as
/// [`Outcome::Refused`] (a ripple closes fully or not at all).
pub(crate) fn shift_clips(project: &mut Project, from: Ticks, delta: Ticks) -> Option<String> {
    if delta == 0 {
        return None;
    }
    let moving = shifted(project, from);
    for id in &moving {
        let Some(clip) = project.clip(*id) else {
            continue;
        };
        if clip.start.saturating_add(delta) < 0 {
            if let Some(partner) = project.partner(*id) {
                return Some(format!(
                    "clip {id} would start before 0: it leads its linked clip {} by {} ticks",
                    partner.id,
                    partner.start.saturating_sub(clip.start)
                ));
            }
        }
    }
    for clip in project.clips.iter_mut() {
        if moving.contains(&clip.id) {
            // Saturating and floored: a caller's delta can never push a
            // clip to a negative start, which `validate` rejects.
            clip.start = clip.start.saturating_add(delta).max(0);
        }
    }
    None
}

/// The bounds a range op works on: snapped, clamped to 0 and put in order,
/// so a drag that ended left of where it began is the same range. `None`
/// for an empty one.
fn ordered_range(project: &Project, from: Ticks, to: Ticks) -> Option<(Ticks, Ticks)> {
    let first = project.snapped(from).max(0);
    let second = project.snapped(to).max(0);
    let (start, end) = if first <= second {
        (first, second)
    } else {
        (second, first)
    };
    (end > start).then_some((start, end))
}

/// Empties `[start, end)` on every unlocked track: both bounds are cut
/// first (`split_under_playhead` IS "split every unlocked clip here"), so
/// afterwards every unlocked clip that touched the range lies entirely
/// inside it, and those are removed.
///
/// Clips on LOCKED tracks are neither split nor removed, even when they lie
/// inside the range: rule 2 is absolute, and a locked track keeps exactly
/// what it had.
///
/// The one thing this does NOT do is decide what happens to the hole, which
/// is the whole difference between a lift and a ripple delete.
fn clear_range(project: &Project, start: Ticks, end: Ticks) -> Result<Project, String> {
    // A splitter has no rule to refuse with — it either cut something or it
    // did not — so both of its non-applied answers mean "nothing was cut at
    // this bound". A splitter that ever gains a rule has to be given a way
    // out of here first: this function answers a `Project`, not an
    // [`Outcome`], so it has nowhere to put a sentence.
    let mut current = match project.split_under_playhead(start)? {
        Outcome::Applied(split) => split,
        Outcome::Identity | Outcome::Refused(_) => project.clone(),
    };
    match current.split_under_playhead(end)? {
        Outcome::Applied(split) => current = split,
        Outcome::Identity | Outcome::Refused(_) => {}
    }

    let unlocked = unlocked_tracks(&current);
    let inside: Vec<u32> = current
        .clips
        .iter()
        .filter(|c| unlocked.contains(&c.track) && c.start >= start && clip_end(c) <= end)
        .map(|c| c.id)
        .collect();
    current.clips.retain(|c| !inside.contains(&c.id));
    Ok(current)
}

// ---- the ops -------------------------------------------------------------

impl Project {
    /// Removes the named clips and closes the holes they leave: for each
    /// removed span, every clip on an UNLOCKED track that starts at or
    /// after the span's end shifts left by the span's length (spec §6).
    ///
    /// The spans are the union of the removed clips' spans and are
    /// processed RIGHT TO LEFT, because shifting for an earlier span moves
    /// the clips a later span's bounds were computed against.
    pub(crate) fn require_track(&self, id: u32) -> Result<&Track, String> {
        self.track(id)
            .ok_or_else(|| format!("no track with id {id}"))
    }

    pub(crate) fn require_media(&self, id: u32) -> Result<&Media, String> {
        self.media(id)
            .ok_or_else(|| format!("no media with id {id}"))
    }

    pub(crate) fn require_track_index(&self, id: u32) -> Result<usize, String> {
        self.track_index(id)
            .ok_or_else(|| format!("no track with id {id}"))
    }

    /// How long a clip showing the WHOLE of `media` is — what `add_clip`
    /// gives one, and therefore how much room `insert_clip` opens and how
    /// much span `overwrite_clip` clears.
    ///
    /// **A timed media's length is THE bound at 1:1**, snapped DOWN
    /// (`source_window.rs`, spec §11): the nearest snap rounds UP past the
    /// end of the file, down-snapped `in + duration × speed ≤
    /// media.duration` holds and the rate is exactly 1. The price is a
    /// frame of the tail, and a media shorter than a frame, which is an
    /// `Err` naming the frame as one with no duration always has been.
    ///
    /// An image has no source bound and keeps the NEAREST snap of its
    /// descriptor's length or of the default — a constant is not on the
    /// grid of a rate that does not divide the timescale (at 30000/1001
    /// five seconds is 3 003 000 ticks, not 3 000 000), and the raw one
    /// made `insert_clip` open a hole wider than the clip it placed.
    pub(crate) fn whole_media_length(&self, media: &Media) -> Result<Ticks, String> {
        match media.kind {
            MediaKind::Lut => Err(crate::lut::lut_not_placeable(media.id)),
            MediaKind::Image if media.duration <= 0 => {
                Ok(self.snapped(DEFAULT_CLIP_DURATION).max(self.frame()))
            }
            MediaKind::Image => Ok(self.snapped(media.duration)),
            MediaKind::Video | MediaKind::Audio if media.duration <= 0 => Err(format!(
                "media {} has no duration ({} ticks)",
                media.id, media.duration
            )),
            MediaKind::Video | MediaKind::Audio => {
                // THE bound (`source_window.rs`) over the whole file from
                // tick 0 at 1:1; a literal 1.0 is always measurable.
                let duration = self
                    .longest_duration_on_grid_of(0, media, 0, 1.0)
                    .or_unbounded()
                    .unwrap_or(0);
                if duration <= 0 {
                    return Err(format!(
                        "media {} is shorter than a frame ({} ticks; a frame is {} ticks)",
                        media.id,
                        media.duration,
                        self.snapped_up(1)
                    ));
                }
                Ok(duration)
            }
        }
    }

    // ---- adding clips ----------------------------------------------------

    /// Places the whole of `media` as one clip at `at` on `track`, source
    /// in 0, with Fit scale when the canvas asks for it and the source
    /// exceeds it (spec §6).
    ///
    /// `video` is `null` for an audio-only file and `audio` is `null` for a
    /// file with no audio track, which is how the inspector knows which
    /// tabs to enable. Refuses when the placement breaks the overlap rule;
    /// `Err` for an unknown track or media, or a media with no usable
    /// duration.
    pub fn add_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        self.require_track(track)?;
        let found = self.require_media(media)?.clone();
        // A drag can start left of zero; the timeline has no negative time.
        let at = self.snapped(at).max(0);

        let duration = self.whole_media_length(&found)?;
        let source = match found.kind {
            MediaKind::Image => Source::Image { media },
            MediaKind::Video | MediaKind::Audio => Source::Media {
                media,
                r#in: 0,
                reversed: false,
            },
            MediaKind::Lut => return Err(crate::lut::lut_not_placeable(media)),
        };

        let has_pixels = found.has_video || matches!(found.kind, MediaKind::Image);
        let video = has_pixels.then(|| VideoProps {
            scale: self.fit_scale(f64::from(found.width), f64::from(found.height)),
            ..VideoProps::default()
        });
        let audio = found.has_audio.then(AudioProps::default);

        let mut next = self.clone();
        let clip = Clip {
            video,
            audio,
            ..Clip::placed(next.allocate_id(), track, at, duration, source)
        };
        self.commit_additions(next, vec![clip])
    }

    // ---- moving -----------------------------------------------------------

    /// Shifts `clips` by `delta` ticks and, when `track` is given, moves
    /// them to that track keeping their relative track offsets (spec §6).
    ///
    /// The EARLIEST clip clamps at 0 and the rest keep their offsets, so a
    /// drag past the start of the timeline compresses nothing. The
    /// destination is computed as an index delta from the first clip of the
    /// selection (by track order, then start), which is what makes a
    /// two-track selection land two tracks apart.
    ///
    /// Refuses when a clip would land outside the track list or the overlap
    /// rule fails on any affected track. A clip that gains a predecessor
    /// overlap and has no transition gets a cross dissolve.
    ///
    /// **A linked partner follows in TIME, not in track** (spec §11 AU-91):
    /// every clip of the closure moves by the one delta, the clamp at 0 is
    /// taken over the closure so a J-cut's lead is kept, and the track delta
    /// is anchored on and applied to the CALLER's clips only — so a sound
    /// half dragged to a track of its own goes alone and its picture stays.
    pub fn move_clips(
        &self,
        clips: &[u32],
        delta: Ticks,
        track: Option<u32>,
    ) -> Result<Outcome, String> {
        let selection = self.selected_clips(clips)?;
        if selection.is_empty() {
            return Ok(Outcome::Identity);
        }
        let closure = self.selected_clips(&self.with_links(clips)?)?;

        // Snapping the delta keeps a dragged clip on the grid: every start
        // is already on it, so a snapped delta lands on it too.
        let mut delta = self.snapped(delta);
        let earliest = closure.iter().map(|c| c.start).min().unwrap_or(0);
        if delta < -earliest {
            delta = -earliest;
        }

        let index_delta = match track {
            None => 0i64,
            Some(destination) => {
                let destination_index = self.require_track_index(destination)? as i64;
                // The anchor is the FIRST clip of the selection in the
                // order the timeline draws — back-most track, then earliest
                // — and the whole selection moves by its offset, which is
                // what keeps a two-track selection two tracks apart.
                let mut keyed: Vec<(usize, Ticks, u32)> = Vec::new();
                for clip in &selection {
                    keyed.push((self.require_track_index(clip.track)?, clip.start, clip.id));
                }
                let anchor = keyed.iter().min().map(|k| k.0).unwrap_or(0) as i64;
                destination_index - anchor
            }
        };

        let mut candidates: Vec<Clip> = Vec::new();
        for clip in &closure {
            let mut moved = (*clip).clone();
            moved.start = moved.start.saturating_add(delta).max(0);
            let named = selection.iter().any(|c| c.id == clip.id);
            if index_delta != 0 && named {
                let from = self.require_track_index(clip.track)? as i64;
                let to = from.saturating_add(index_delta);
                // A selection dragged off either end of the track list is a
                // refusal and not a clamp — clamping would silently stack
                // two clips on one track — and it says so in `move_track`'s
                // own words for the same mistake.
                let Some(destination) = usize::try_from(to)
                    .ok()
                    .and_then(|index| self.tracks.get(index))
                else {
                    return Ok(Outcome::Refused(format!(
                        "clip {} would land on track index {to}, which is out of range (0..{})",
                        clip.id,
                        self.tracks.len()
                    )));
                };
                moved.track = destination.id;
            }
            candidates.push(moved);
        }

        self.commit_replacements(candidates)
    }

    /// The named clips, deduplicated, in the order given. `Err` on an
    /// unknown id — every multi-clip op names its clips explicitly, so a
    /// stale id is a caller bug, not a refusal.
    pub(crate) fn selected_clips(&self, clips: &[u32]) -> Result<Vec<&Clip>, String> {
        let mut out: Vec<&Clip> = Vec::new();
        for id in clips {
            let clip = self.require_clip(*id)?;
            if !out.iter().any(|c| c.id == clip.id) {
                out.push(clip);
            }
        }
        Ok(out)
    }

